    /// <summary>
    /// Encrypts group call data before sending them over network using tgcalls
    /// </summary>
    public Task<TdLib.TdApi.Objects.Data> EncryptGroupCallDataAsync(int groupCallId = default, GroupCallDataChannel dataChannel = default, byte[] data = default, int unencryptedPrefixSize = default)
    {

           using var activity =  StartCallActivity("EncryptGroupCallDataAsync", typeof(EncryptGroupCallData).FullName ?? "EncryptGroupCallDataAsync");

           try
           {
             return client.EncryptGroupCallDataAsync(groupCallId, dataChannel, data, unencryptedPrefixSize);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
